/* nepui - OTP Field */

.np-otp-field,
[data-np-otp-field] {
  --spacing: 0.25rem;
  --np-otp-field-gap: calc(var(--spacing) * 2);
  --np-otp-field-slot-size: calc(var(--spacing) * 9);
  --np-otp-field-font-size: 1rem;
  --np-otp-field-radius: var(--np-radius-md);
  --np-otp-field-border: var(--np-input, var(--np-border));
  --np-otp-field-bg: transparent;
  --np-otp-field-placeholder: var(--np-muted-foreground);
  --np-otp-field-invalid-border: var(--np-destructive);
  --np-otp-field-invalid-ring: color-mix(
    in oklch,
    var(--np-destructive),
    transparent 80%
  );
  --np-otp-field-separator-width: calc(var(--spacing) * 3);
  --np-otp-field-separator-thickness: calc(var(--spacing) * 0.5);
  --np-otp-field-separator-color: var(--np-muted-foreground);

  box-sizing: border-box;
  display: flex;
  align-items: center;
  gap: var(--np-otp-field-gap);
  width: fit-content;
}

:is(.np-otp-field, [data-np-otp-field]):is(.np-otp-field-sm, [data-size="sm"]) {
  --np-otp-field-gap: calc(var(--spacing) * 1.5);
  --np-otp-field-slot-size: calc(var(--spacing) * 8);
  --np-otp-field-font-size: 0.875rem;
  --np-otp-field-separator-width: calc(var(--spacing) * 2);
}

:is(.np-otp-field, [data-np-otp-field]):is(.np-otp-field-lg, [data-size="lg"]) {
  --np-otp-field-gap: calc(var(--spacing) * 2.5);
  --np-otp-field-slot-size: calc(var(--spacing) * 11);
  --np-otp-field-font-size: 1.25rem;
  --np-otp-field-separator-width: calc(var(--spacing) * 4);
}

.np-otp-field-input,
[data-np-otp-field-input] {
  box-sizing: border-box;
  display: block;
  flex: none;
  width: var(--np-otp-field-slot-size);
  height: var(--np-otp-field-slot-size);
  margin: 0;
  padding: 0;
  border: 1px solid var(--np-otp-field-border);
  border-radius: var(--np-otp-field-radius);
  background-color: var(--np-otp-field-bg);
  color: inherit;
  font-family: inherit;
  font-size: 1rem;
  font-variant-numeric: tabular-nums;
  line-height: 1;
  text-align: center;
  outline: none;
  transition:
    color 150ms ease,
    background-color 150ms ease,
    border-color 150ms ease,
    box-shadow 150ms ease;
}

@media (min-width: 48rem) {
  .np-otp-field-input,
  [data-np-otp-field-input] {
    font-size: var(--np-otp-field-font-size);
  }
}

:is(.np-otp-field-input, [data-np-otp-field-input])::placeholder {
  color: var(--np-otp-field-placeholder);
}

:is(.np-otp-field-input, [data-np-otp-field-input]):focus-visible {
  border-color: var(--np-ring);
  box-shadow: 0 0 0 3px color-mix(in oklch, var(--np-ring), transparent 50%);
}

:is(.np-otp-field-input, [data-np-otp-field-input]):focus-visible::placeholder {
  color: transparent;
}

:is(.np-otp-field-input, [data-np-otp-field-input]):is(
  :disabled,
  [aria-disabled="true"],
  [data-disabled]
) {
  opacity: 0.5;
  pointer-events: none;
}

:is(.np-otp-field-input, [data-np-otp-field-input]):is(
  [aria-invalid="true"],
  [aria-invalid],
  [data-invalid]
) {
  border-color: var(--np-otp-field-invalid-border);
  box-shadow: 0 0 0 3px var(--np-otp-field-invalid-ring);
}

.np-otp-field-separator,
[data-np-otp-field-separator] {
  flex: none;
  width: var(--np-otp-field-separator-width);
  height: var(--np-otp-field-separator-thickness);
  border-radius: var(--np-radius-full, 9999px);
  background-color: var(--np-otp-field-separator-color);
}

:is(.dark, [data-theme="dark"]) :is(.np-otp-field, [data-np-otp-field]) {
  --np-otp-field-bg: color-mix(
    in oklab,
    var(--np-otp-field-border) 30%,
    transparent
  );
  --np-otp-field-invalid-border: color-mix(
    in oklab,
    var(--np-destructive) 50%,
    transparent
  );
  --np-otp-field-invalid-ring: color-mix(
    in oklab,
    var(--np-destructive) 20%,
    transparent
  );
}

@media (prefers-color-scheme: dark) {
  :root:not(.light, [data-theme="light"])
    :is(.np-otp-field, [data-np-otp-field]) {
    --np-otp-field-bg: color-mix(
      in oklab,
      var(--np-otp-field-border) 30%,
      transparent
    );
    --np-otp-field-invalid-border: color-mix(
      in oklab,
      var(--np-destructive) 50%,
      transparent
    );
    --np-otp-field-invalid-ring: color-mix(
      in oklab,
      var(--np-destructive) 20%,
      transparent
    );
  }
}

@media (prefers-reduced-motion: reduce) {
  .np-otp-field-input,
  [data-np-otp-field-input] {
    transition: none;
  }
}

;(function () {
  var rootSelector = ".np-otp-field, [data-np-otp-field]"
  var inputSelector = ".np-otp-field-input, [data-np-otp-field-input]"
  var patterns = {
    numeric: /[0-9]/,
    alpha: /[a-zA-Z]/,
    alphanumeric: /[a-zA-Z0-9]/,
    none: /[\s\S]/,
  }

  function slots(root) {
    return Array.prototype.slice.call(root.querySelectorAll(inputSelector))
  }

  function clean(root, text) {
    var pattern =
      patterns[root.getAttribute("data-validation")] || patterns.numeric
    if (root.hasAttribute("data-uppercase")) text = text.toUpperCase()
    return Array.prototype.filter
      .call(text, function (character) {
        return pattern.test(character)
      })
      .join("")
  }

  function readValue(root) {
    return slots(root)
      .map(function (slot) {
        return slot.value
      })
      .join("")
  }

  function updateHidden(root) {
    var hidden = root.querySelector('input[type="hidden"]')
    if (hidden) hidden.value = readValue(root)
  }

  function sync(root) {
    updateHidden(root)
    var list = slots(root)
    var complete =
      list.length > 0 &&
      list.every(function (slot) {
        return slot.value !== ""
      })
    if (!complete) return
    root.dispatchEvent(
      new CustomEvent("np-otp-complete", {
        bubbles: true,
        detail: { value: readValue(root) },
      })
    )
    if (root.hasAttribute("data-auto-submit")) {
      var form = root.closest("form")
      if (form && form.requestSubmit) form.requestSubmit()
    }
  }

  function fill(root, start, text) {
    var list = slots(root)
    var characters = clean(root, text)
    var index = start

    for (
      var i = 0;
      i < characters.length && index < list.length;
      i++, index++
    ) {
      list[index].value = characters.charAt(i)
    }

    var nextIndex = Math.min(index, list.length - 1)
    list[nextIndex].focus()

    sync(root)
  }

  function slotOf(event) {
    var target = event.target
    if (!target || !target.matches || !target.matches(inputSelector))
      return null
    var root = target.closest(rootSelector)
    return root ? { root: root, slot: target, list: slots(root) } : null
  }

  document.addEventListener("input", function (event) {
    var hit = slotOf(event)
    if (!hit) return

    var text = event.data || hit.slot.value
    var index = hit.list.indexOf(hit.slot)

    if (!text) {
      sync(hit.root)
      return
    }

    hit.slot.value = ""

    fill(hit.root, index, text)
  })

  document.addEventListener("keydown", function (event) {
    var hit = slotOf(event)
    if (!hit) return
    var index = hit.list.indexOf(hit.slot)
    var target = null
    if (event.key === "Backspace" && hit.slot.value === "" && index > 0) {
      target = hit.list[index - 1]
      target.value = ""
      sync(hit.root)
    } else if (event.key === "ArrowLeft") {
      target = hit.list[Math.max(index - 1, 0)]
    } else if (event.key === "ArrowRight") {
      target = hit.list[Math.min(index + 1, hit.list.length - 1)]
    } else if (event.key === "Home") {
      target = hit.list[0]
    } else if (event.key === "End") {
      target = hit.list[hit.list.length - 1]
    }
    if (target) {
      event.preventDefault()
      target.focus()
    }
  })

  document.addEventListener("paste", function (event) {
    var hit = slotOf(event)
    if (!hit) return
    var text = (event.clipboardData || window.clipboardData).getData("text")
    event.preventDefault()
    var start =
      clean(hit.root, text).length >= hit.list.length
        ? 0
        : hit.list.indexOf(hit.slot)
    fill(hit.root, start, text)
  })

  document.addEventListener("focusin", function (event) {
    var hit = slotOf(event)
    if (hit) hit.slot.select()
  })

  function init(root) {
    root.querySelectorAll(inputSelector).forEach(function (slot) {
      slot.removeAttribute("maxlength")
    })
    root.querySelectorAll(rootSelector).forEach(updateHidden)
  }

  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", function () {
      init(document)
    })
  } else {
    init(document)
  }
})()
